//! The scaffold as suite YAML: serde_yaml writes every value, so quoting is
//! never hand-made; the lines around them carry the comments.

use super::Scaffold;

pub fn render(s: &Scaffold) -> Result<String, String> {
    let mut out = String::new();
    out.push_str(&format!(
        "# Generated by `atalanta api scaffold` from {} ({}): {} tests, {} requests,\n\
         # {} checks read from the response schemas.\n",
        one_line(&s.source),
        one_line(&s.title),
        s.tests.len(),
        s.requests(),
        s.checks()
    ));
    if !s.variables.is_empty() {
        out.push_str("#\n# Set these before a run (environment or --env-file):\n");
        let width = s.variables.iter().map(|(n, _)| n.len()).max().unwrap_or(0);
        for (name, what) in &s.variables {
            out.push_str(&format!("#   {name:width$}  {}\n", one_line(what)));
        }
    }
    out.push_str("config:\n  http:\n");
    out.push_str(&indent(&yaml(&s.config)?, 4));
    out.push_str("tests:\n");
    for t in &s.tests {
        out.push_str(&format!(
            "  - name: {}\n    steps:\n",
            yaml(&t.name)?.trim_end()
        ));
        for step in &t.steps {
            out.push_str(&format!("      # {}\n", one_line(&step.label)));
            for note in &step.notes {
                out.push_str(&format!("      # {}\n", one_line(note)));
            }
            out.push_str("      - http:\n");
            out.push_str(&indent(&yaml(&step.request)?, 10));
        }
    }
    Ok(out)
}

/// `text` for a `#` comment: one line. A title, operationId or path from
/// the spec holding a line break (`\n`, `\r`, U+0085, U+2028, U+2029: all
/// end a YAML comment) would otherwise write the rest of itself into the
/// suite as YAML of its own.
fn one_line(text: &str) -> String {
    text.chars()
        .map(|c| {
            if c.is_control() || matches!(c, '\u{2028}' | '\u{2029}') {
                ' '
            } else {
                c
            }
        })
        .collect()
}

fn indent(text: &str, by: usize) -> String {
    let pad = " ".repeat(by);
    text.lines()
        .map(|l| {
            if l.is_empty() {
                "\n".to_string()
            } else {
                format!("{pad}{l}\n")
            }
        })
        .collect()
}

fn yaml<T: serde::Serialize>(v: &T) -> Result<String, String> {
    serde_yaml::to_string(v).map_err(|e| e.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_comment_stays_one_line() {
        for brk in ["\n", "\r", "\u{85}", "\u{2028}", "\u{2029}"] {
            let text = format!("a{brk}tests: x");
            assert!(!one_line(&text).contains(brk), "{brk:?}");
        }
        assert_eq!(
            one_line("GET /pets/{id} (getPet)"),
            "GET /pets/{id} (getPet)"
        );
    }
}
